  function common(value){return record(value)&&value.contract_version===1&&value.cardinality_policy===policy&&value.read_only===true&&value.complete===true&&value.erp_connected===false&&value.sqlite_read_only===true&&value.sqlite_read_transaction===true&&value.resources_written===false&&value.nx_files_written===false&&value.automatic_approval===false&&hex(value.snapshot_sha256);}
