  function variantChanged(){cancelRead('variant');cancelRead('currentArticle');currentVariant=null;variantStale=false;clearCurrentArticle();el('navigation-state').textContent='Variante geändert; heutige Zuordnung ausdrücklich lesen. Kein Artikelziel automatisch geändert.';el('variant-detail').textContent='';el('variant-state').textContent='Heutigen Artikelbezug ausdrücklich lesen.';controls();}
